def bson_utc(value: datetime) -> datetime:
    """Match PyMongo's millisecond storage so POST, PUT and GET agree exactly."""
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError("Date/time must include a timezone")
    value = value.astimezone(timezone.utc)
    return value.replace(microsecond=value.microsecond // 1000 * 1000)


class RentalFields(BaseModel):
    model_config = ConfigDict(extra="forbid")

    listingTitle: Annotated[str, Field(strict=True, min_length=1, max_length=100)]
    description: Annotated[str | None, Field(strict=True, max_length=5000)] = None
    status: Status = "available"
    propertyType: PropertyType
    availableFrom: AwareDatetime

    @field_validator("listingTitle", mode="before")
    @classmethod
    def trim_title(cls, value):
        return value.strip() if isinstance(value, str) else value

    @field_validator("availableFrom", mode="before")
    @classmethod
    def require_iso_datetime(cls, value):
        if isinstance(value, datetime):
            return value
        if not isinstance(value, str) or ISO_DATETIME.fullmatch(value) is None:
            raise ValueError("Use ISO 8601 YYYY-MM-DDTHH:MM:SS[.ffffff]Z or an explicit ±HH:MM offset")
        return value

    @field_validator("availableFrom")
    @classmethod
    def normalize_utc(cls, value):
        return bson_utc(value)

class RentalCreate(RentalFields):
    """Server assigns the identifier and both timestamps; those inputs are forbidden."""


class RentalUpdate(RentalFields):
    """Full PUT: all required fields; omitted status/description reset to defaults."""


class RentalResponse(RentalFields):
    id: str = Field(pattern=r"^[0-9a-f]{24}$")
    created_at: AwareDatetime
    updated_at: AwareDatetime

# Python str.strip()'s whitespace set, explicit because MongoDB's PCRE defaults
# need not classify Unicode whitespace the same way as Python.
NONSPACE = (r"[^\x09-\x0d\x1c-\x20" "\u0085\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]")

RENTAL_VALIDATOR = {
    "$jsonSchema": {
        "bsonType": "object",
        "title": "Rental listing",
        "additionalProperties": False,
        "required": ["listingTitle", "status", "propertyType", "availableFrom", "created_at", "updated_at"],
        "properties": {
            "_id": {"bsonType": "objectId"},
            "listingTitle": {
                "bsonType": "string", "minLength": 1, "maxLength": 100,
                # The negative lookahead anchors the absolute end, including a final newline.
                "pattern": rf"\A{NONSPACE}(?:[\s\S]*{NONSPACE})?(?![\s\S])",
                "description": "Required trimmed nonblank title, at most 100 characters",
            },
            "description": {"bsonType": ["string", "null"], "maxLength": 5000},
            "status": {"bsonType": "string", "enum": ["available", "reserved", "rented"]},
            "propertyType": {"bsonType": "string", "enum": ["apartment", "house", "condo", "townhouse"]},
            "availableFrom": {"bsonType": "date"},
            "created_at": {"bsonType": "date"},
            "updated_at": {"bsonType": "date"},
        },
    }
}

@contextmanager
def _operation(self, operation):
    try:
        yield
    except HW6Error:
        raise
    except Exception as error:
        if isinstance(error, OperationFailure) and error.code == 121:
            public_error = DocumentValidationFailed()
        elif isinstance(error, PyMongoError):
            public_error = StorageUnavailable()
        else:
            public_error = HW6Error()
        # Never log exception text or traceback: driver errors can contain credentials.
        logger.error("hw06_documents operation=%s code=%s error_type=%s", operation,
                     public_error.code, type(error).__name__)
        raise public_error from None

def create(self, payload: RentalCreate) -> RentalResponse:
    with self._operation("create"):
        self.prepare_collection()
        now = bson_utc(self.clock())
        document = {**payload.model_dump(), "created_at": now, "updated_at": now}
        result = self.collection.insert_one(document)
        document["_id"] = result.inserted_id
        return self._response(document)

def list(self) -> list[RentalResponse]:
    with self._operation("list"):
        self.prepare_collection()
        return [self._response(document) for document in
                self.collection.find().sort([("created_at", 1), ("_id", 1)])]

def get(self, identifier: str) -> RentalResponse:
    oid = self._object_id(identifier)
    with self._operation("get"):
        self.prepare_collection()
        return self._response(self.collection.find_one({"_id": oid}))

def create_router(service: DocumentService, *, current_user_dependency=require_user) -> APIRouter:
    router = APIRouter(prefix="/api/doc-rentals", tags=["document rentals"],
                       dependencies=[Depends(current_user_dependency)])

    @router.post("", response_model=RentalResponse, status_code=201)
    def create_rental(payload: RentalCreate):
        return service.create(payload)

    @router.get("", response_model=list[RentalResponse])
    def list_rentals():
        return service.list()

    @router.get("/{rental_id}", response_model=RentalResponse)
    def get_rental(rental_id: str):
        return service.get(rental_id)

    @router.put("/{rental_id}", response_model=RentalResponse)
    def update_rental(rental_id: str, payload: RentalUpdate):
        return service.update(rental_id, payload)

    @router.delete("/{rental_id}", status_code=204)
    def delete_rental(rental_id: str):
        service.delete(rental_id)
        return Response(status_code=204)

    return router
